// Pathfinder 2e Remaster rules data, generated by `scripts/pf2e-data.ts` from Archives of
// Nethys (ORC content from the setting-neutral rulebooks only, nothing from Golarion setting
// books or named for its deities and places; see `data/pf2e/NOTICE.md`). Every record keeps
// its AoN id and the book and printed page it comes from. Deities are Paizo Reserved Material,
// included under Paizo's Community Use Policy (see the notice); book art is never included.
import type { Pf2eAttr, Pf2eRank } from '~/types/sheets'

export interface Pf2eSource {
  book: string
  /** Printed page; absent for web-only articles. */
  page?: number
}

export type Pf2eRarity = 'common' | 'uncommon' | 'rare' | 'unique'

/**
 * 1–3 actions, a reaction, a free action, a range or choice of those ("1 to 3", "free or 1",
 * "2 to 2 rounds"), or a time for activities ("1 minute").
 */
export type Pf2eActionCost = 1 | 2 | 3 | 'reaction' | 'free' | string

export interface Pf2eRecord {
  /** AoN document id, e.g. `feat-4775`: unique and stable. */
  id: string
  name: string
  source: Pf2eSource
  rarity: Pf2eRarity
  traits: string[]
  /** Rules text as markdown, without the title, traits, source and stat lines. */
  text: string
  /** Names of the legacy entries this one replaces. */
  replaces?: string[]
  /**
   * What AoN's entry leaves out that the book prints (a druidic order's skill, feat and order
   * spell; an awakened animal's Hit Points), for the builder to say instead of guessing.
   */
  gap?: string
}

export interface Pf2eClassFeature {
  id: string
  name: string
  level: number
  text: string
}

export interface Pf2eSubclassOption extends Pf2eRecord {
  /** The book's name for the choice, e.g. "Bard Muse", "Druidic Order". */
  kind: string
  /** For options with levels (runesmith runes, commander tactics). */
  level?: number
  /** Skills the option makes you trained in (a patron's, a rogue's racket…). */
  skills: string[]
  /** The spell tradition it sets (a sorcerer's bloodline, a witch's patron, an eidolon). */
  traditions: string[]
  /** Witch lessons: "Basic", "Greater" or "Major". */
  lessonType?: string
  /** Commander tactics: "Mobility", "Offensive"… */
  tacticType?: string
  /** Exemplar ikons and runesmith runes: what it's imbued into or drawn on. */
  usage?: string
  frequency?: string
  requirements?: string
  /** Summoner eidolons: their tradition and home plane. */
  tradition?: string
  homePlane?: string
}

export interface Pf2eClassDef extends Pf2eRecord {
  slug: string
  /** Key attribute; two when the class lets you choose. */
  keyAttributes: Pf2eAttr[]
  /** Hit Points per level, before CON. */
  hp: number
  perception: Pf2eRank
  saves: { fortitude: Pf2eRank; reflex: Pf2eRank; will: Pf2eRank }
  /** Initial proficiency lines as printed ("Trained in martial weapons"). */
  skills: string[]
  attacks: string[]
  defenses: string[]
  /** Spell tradition(s), for spellcasting classes. */
  traditions: string[]
  /** Class advancement table: what each level grants, by the book's names. */
  advancement: { level: number; features: string[] }[]
  /** Spells per day for slot casters: cantrips, then slots for ranks 1–10. */
  spellSlots?: { level: number; cantrips: number; slots: number[] }[]
  features: Pf2eClassFeature[]
  subclasses: Pf2eSubclassOption[]
}

export interface Pf2eAncestryDef extends Pf2eRecord {
  slug: string
  hp: number
  size: string[]
  speed: number
  /** Attribute boosts: attribute names, or "Free" once per free boost (Human: two "Free"). */
  boosts: string[]
  flaws: string[]
  languages: string[]
  vision?: string
}

/** Speeds by movement type, in feet. */
export type Pf2eSpeeds = Partial<Record<'land' | 'climb' | 'swim' | 'fly' | 'burrow', number>>

export interface Pf2eHeritageDef extends Pf2eRecord {
  /**
   * The ancestry's slug (`Pf2eAncestryDef.slug`; feats name ancestries by name instead).
   * Absent for versatile heritages.
   */
  ancestry?: string
  versatile: boolean
  /** Speeds the heritage text grants ("a land Speed of 20 feet, a climb Speed of 20 feet"). */
  speeds?: Pf2eSpeeds
}

export interface Pf2eBackgroundDef extends Pf2eRecord {
  /** Attribute names it may boost (one of them, plus a free boost). */
  boosts: string[]
  /**
   * Skills it trains outright, plus AoN's wording for a Lore the player names ("Lore related
   * to the terrain you worked in").
   */
  skills: string[]
  /**
   * Skills to pick from: "your choice of the Arcana, Nature, Occultism, or Religion skill",
   * "the Legal Lore skill or Warfare Lore skill". No options means any skill.
   */
  skillChoices?: { options: string[]; count: number }[]
  /** Trained in your deity's skill (Raised by Belief): the builder fills it in from the deity. */
  deitySkill?: boolean
  feats: string[]
}

export interface Pf2eFeatDef extends Pf2eRecord {
  level: number
  actions?: Pf2eActionCost
  prerequisites?: string
  trigger?: string
  requirements?: string
  frequency?: string
  cost?: string
  /** Who may take an uncommon feat without other access ("You are from Ustalav."). */
  access?: string
  /** Exemplar feats: the ikon it's imbued into. */
  usage?: string
  duration?: string
  /** Class names whose feat list includes it (by trait). */
  classes: string[]
  /** Ancestry or versatile heritage names whose feat list includes it. */
  ancestries: string[]
  archetypes: string[]
  general: boolean
  skill: boolean
}

/** The class options that list a spell, by name ("Lesson of Shadow", a deity's domain…). */
export interface Pf2eSpellLinks {
  domains?: string[]
  bloodlines?: string[]
  mysteries?: string[]
  lessons?: string[]
  patronThemes?: string[]
}

/** `step` for "Heightened (+N)"; `ranks` for each "Heightened (Nth)" entry. A spell may have both. */
export interface Pf2eHeightening {
  step?: number
  ranks: number[]
}

export interface Pf2eSpellDef extends Pf2eRecord, Pf2eSpellLinks {
  rank: number
  kind: 'spell' | 'cantrip' | 'focus'
  traditions: string[]
  actions?: Pf2eActionCost
  range?: string
  area?: string
  targets?: string
  duration?: string
  /** Saving throw or defense, e.g. "basic Reflex". */
  defense?: string
  trigger?: string
  requirements?: string
  /** A material or other cost to cast (rituals and a few spells). */
  cost?: string
  heightened?: Pf2eHeightening
  /** A psychic's amped heightening ("Amp Heightened (+2)"). */
  ampHeightened?: Pf2eHeightening
  /** Focus spells and class cantrips (compositions, hexes): the classes they belong to (a domain
   * spell is the cleric's). */
  classes: string[]
}

export interface Pf2eWeaponDef extends Pf2eRecord {
  level: number
  /** Price in copper pieces. */
  price: number
  bulk: number
  hands: string
  damage: string
  damageTypes: string[]
  category: string
  group: string
  type: 'Melee' | 'Ranged'
  range?: number
  /** Actions to reload, or the printed time when it isn't counted in actions ("1 minute"). */
  reload?: number | string
}

export interface Pf2eArmorDef extends Pf2eRecord {
  level: number
  price: number
  bulk: number
  category: string
  group?: string
  ac: number
  dexCap?: number
  checkPenalty: number
  speedPenalty: number
  strength?: number
}

export interface Pf2eShieldDef extends Pf2eRecord {
  level: number
  price: number
  bulk: number
  ac: number
  hardness: number
  hp: number
  speedPenalty: number
}

export interface Pf2eConditionDef extends Pf2eRecord {
  /** Has a value, like frightened 2. */
  valued: boolean
}

export interface Pf2eActionDef extends Pf2eRecord {
  actions?: Pf2eActionCost
  trigger?: string
  requirements?: string
  frequency?: string
  cost?: string
}

export type Pf2eTraitDef = Pf2eRecord

/** A deity (Reserved Material, under Paizo's Community Use Policy). */
export interface Pf2eDeityDef extends Pf2eRecord {
  epithet?: string
  category: string
  edicts: string
  anathema: string
  areasOfConcern: string[]
  /** The divine attribute options (a cleric picks one). */
  attributes: Pf2eAttr[]
  /** Heal, harm or both. */
  divineFont: string[]
  /** e.g. "can choose holy or unholy"; absent when the deity grants none. */
  sanctification?: string
  /** The divine skill. */
  skill: string[]
  favoredWeapons: string[]
  domains: string[]
  alternateDomains: string[]
  /** Spells a cleric of this deity adds to their list, by name. */
  clericSpells: string[]
}

/** What a modifier applies to. `checks` is every check and DC; `saves` every saving throw. */
export type Pf2eSelector =
  | 'ac'
  | 'attack'
  | 'damage'
  | 'perception'
  | 'fortitude'
  | 'reflex'
  | 'will'
  | 'saves'
  | 'skills'
  | 'checks'
  | 'speed'

/**
 * One structured piece of what an ability does, read by `utils/pf2eEffects.ts`. Hand-written
 * per ability in `data/pf2e/effects.ts` from its rules text; anything the kinds can't say
 * stays in `note` for the player.
 */
export type Pf2eEffect =
  /**
   * A bonus or penalty. `melee` limits it to melee Strikes, `weapons` to agile or finesse
   * ones, `skills` to the named skills; `agileHalf` halves it for agile attacks; `byLevel`
   * replaces `value` from a level on (the last entry at or below the hero's level).
   */
  | {
      kind: 'modifier'
      selector: Pf2eSelector[]
      value: number
      type: 'status' | 'circumstance' | 'item' | 'untyped'
      melee?: boolean
      agileHalf?: boolean
      weapons?: 'agileFinesse'
      skills?: string[]
      byLevel?: [level: number, value: number][]
      /** Effects whose bonus of the same type this one adds to instead of the higher counting. */
      cumulativeWith?: string[]
    }
  /** A different multiple attack penalty (the Flurry edge against hunted prey). */
  | { kind: 'map'; second: number; third: number; agileSecond: number; agileThird: number }
  /** Damage with finesse melee Strikes uses this attribute when it's higher (Thief). */
  | { kind: 'damageAttribute'; attr: Pf2eAttr }
  /** Damage by the Strike's proficiency rank (weapon specialization). */
  | { kind: 'specialization'; damage: Partial<Record<Pf2eRank, number>> }
  /** A condition the effect gives (Enlarge: clumsy 1; Haste: quickened). */
  | { kind: 'condition'; name: string; value?: number }
  /** A Dexterity cap on AC (Mountain Stance: +0). */
  | { kind: 'dexCap'; value: number }
  /** Extra damage dice on Strikes while a condition holds (sneak attack on an off-guard foe). */
  | {
      kind: 'damageDice'
      /** Dice by level: the last entry at or below the hero's level applies. */
      dice: [level: number, dice: string][]
      when: 'offGuard' | 'huntedPrey' | 'stratagem'
      /** Which Strikes: agile, finesse or ranged (sneak attack). */
      weapons?: 'agileFinesseRanged'
      label: string
    }
  /** Temporary Hit Points when turned on: level + CON (Rage). */
  | { kind: 'tempHp'; formula: 'levelPlusCon' }
  /** The dying value at which the hero dies (Diehard: 5). */
  | { kind: 'deathAt'; value: number }
  /** Change to recovery check DCs (Toughness: −1). */
  | { kind: 'recoveryDc'; value: number }

export interface Pf2eEffectDef {
  /** The feat, class feature, action or spell it belongs to, by name. */
  name: string
  source: Pf2eSource
  /**
   * `permanent`: on whenever the hero has the ability. `toggle`: the hero turns it on.
   * `given`: an ally's effect on the hero (Bless), chosen from a list.
   */
  mode: 'permanent' | 'toggle' | 'given'
  effects: Pf2eEffect[]
  /** Values for a `given` effect that scales (Heroism +1/+2/+3); modifiers use the chosen one. */
  values?: number[]
  /** Only while this other effect is on (the ranger's edges need Hunt Prey). */
  requires?: string
  /** A toggle that ends when the hero falls unconscious (Rage). */
  endsWhenUnconscious?: boolean
  /** Rules the effect can't apply itself, shown while it's on. */
  note?: string
}
